pragma solidity ^0.8.19;

import "@pythnetwork/entropy-sdk-solidity/IEntropy.sol";
import "@pythnetwork/entropy-sdk-solidity/IEntropyConsumer.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy private entropy;

    struct Game {
        address player;
        uint256 wager;
        bool prediction; // true = heads, false = tails
        bool resolved;
        bool won;
        uint64 sequenceNumber;
    }

    mapping(uint64 => Game) public games;
    mapping(address => uint256) public winnings;

    event GameCreated(address indexed player, uint64 sequenceNumber, bool prediction, uint256 wager);
    event GameResolved(address indexed player, uint64 sequenceNumber, bool result, bool won, uint256 payout);

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
    }

    function flipCoin(bool prediction) external payable {
        require(msg.value > 0, "Must wager some ETH");

        address provider = entropy.getDefaultProvider();
        uint256 fee = entropy.getFee(provider);
        require(msg.value > fee, "Insufficient fee for randomness");

        uint256 wager = msg.value - fee;

        uint64 sequenceNumber = entropy.requestWithCallback{value: fee}(
            provider,
            bytes32(uint256(uint160(msg.sender))) // user commitment
        );

        games[sequenceNumber] = Game({
            player: msg.sender,
            wager: wager,
            prediction: prediction,
            resolved: false,
            won: false,
            sequenceNumber: sequenceNumber
        });

        emit GameCreated(msg.sender, sequenceNumber, prediction, wager);
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) internal override {
        Game storage game = games[sequenceNumber];
        require(!game.resolved, "Game already resolved");
        require(game.player != address(0), "Game does not exist");

        // Convert random number to coin flip (heads = true, tails = false)
        bool result = uint256(randomNumber) % 2 == 1;
        bool won = (result == game.prediction);

        game.resolved = true;
        game.won = won;

        uint256 payout = 0;
        if (won) {
            payout = game.wager * 2; // Double the wager
            winnings[game.player] += payout;
        }

        emit GameResolved(game.player, sequenceNumber, result, won, payout);
    }

    function withdraw() external {
        uint256 amount = winnings[msg.sender];
        require(amount > 0, "No winnings to withdraw");

        winnings[msg.sender] = 0;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Withdrawal failed");
    }

    function getEntropyAddress() external view returns (address) {
        return address(entropy);
    }

    receive() external payable {}
}"}

