import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import './App.css'

const COIN_FLIP_ABI = [
  "function flipCoin(bool prediction) external payable",
  "function withdraw() external", 
  "function winnings(address) external view returns (uint256)",
  "function games(uint64) external view returns (address, uint256, bool, bool, bool, uint64)",
  "event GameCreated(address indexed player, uint64 sequenceNumber, bool prediction, uint256 wager)",
  "event GameResolved(address indexed player, uint64 sequenceNumber, bool result, bool won, uint256 payout)"
]

// Replace with your deployed contract address
const CONTRACT_ADDRESS = "0x..." // You'll need to deploy the contract first

function App() {
  const [account, setAccount] = useState('')
  const [contract, setContract] = useState(null)
  const [winnings, setWinnings] = useState('0')
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (window.ethereum) {
      const provider = new ethers.BrowserProvider(window.ethereum)
      const contractInstance = new ethers.Contract(CONTRACT_ADDRESS, COIN_FLIP_ABI, provider)
      setContract(contractInstance)
    }
  }, [])

  const connectWallet = async () => {
    try {
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' })
      setAccount(accounts[0])

      if (contract) {
        const userWinnings = await contract.winnings(accounts[0])
        setWinnings(ethers.formatEther(userWinnings))
      }
    } catch (error) {
      console.error('Error connecting wallet:', error)
    }
  }

  const flipCoin = async (prediction) => {
    if (!contract || !account) return

    try {
      setLoading(true)
      const provider = new ethers.BrowserProvider(window.ethereum)
      const signer = await provider.getSigner()
      const contractWithSigner = contract.connect(signer)

      // Send 0.001 ETH (includes fee for entropy + wager)
      const tx = await contractWithSigner.flipCoin(prediction, {
        value: ethers.parseEther("0.001")
      })

      await tx.wait()
      alert(`Coin flip submitted! Result will be available shortly.`)

      // Refresh winnings
      const userWinnings = await contract.winnings(account)
      setWinnings(ethers.formatEther(userWinnings))
    } catch (error) {
      console.error('Error flipping coin:', error)
      alert('Error: ' + error.message)
    } finally {
      setLoading(false)
    }
  }

  const withdraw = async () => {
    if (!contract || !account) return

    try {
      setLoading(true)
      const provider = new ethers.BrowserProvider(window.ethereum)
      const signer = await provider.getSigner()
      const contractWithSigner = contract.connect(signer)

      const tx = await contractWithSigner.withdraw()
      await tx.wait()

      alert('Winnings withdrawn!')
      setWinnings('0')
    } catch (error) {
      console.error('Error withdrawing:', error)
      alert('Error: ' + error.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="App">
      <h1>🪙 Pyth Entropy Coin Flip</h1>
      <p>Provably fair coin flips using Pyth Network's verifiable randomness</p>

      {!account ? (
        <button onClick={connectWallet}>Connect Wallet</button>
      ) : (
        <div>
          <p>Connected: {account.substring(0, 6)}...{account.substring(38)}</p>
          <p>Winnings: {winnings} ETH</p>

          <div className="game-section">
            <h2>Flip a Coin (0.001 ETH)</h2>
            <div className="buttons">
              <button 
                onClick={() => flipCoin(true)} 
                disabled={loading}
                className="heads-btn"
              >
                🟡 Heads
              </button>
              <button 
                onClick={() => flipCoin(false)} 
                disabled={loading}
                className="tails-btn"
              >
                ⚫ Tails
              </button>
            </div>
          </div>

          {parseFloat(winnings) > 0 && (
            <button onClick={withdraw} disabled={loading} className="withdraw-btn">
              Withdraw Winnings
            </button>
          )}
        </div>
      )}

      {loading && <p>Processing...</p>}
    </div>
  )
}

export default App

